import json
def solve(g):
    # mirror vertically, solve with "gravity toward bottom line", mirror back
    H,W=len(g),len(g[0])
    f=[r[::-1] for r in g]          # flip upside down
    f=comps=f
    def get_comps(flipg):
        Hh,Ww=len(flipg),len(flipg[0]); seen=[[False]*Ww for _ in range(Hh)]; out=[]
        def flood(r,c):
            comp=[];stack=[(r,c)];seen[r][c]=True
            while stack:
                rr,cc=stack.pop();comp.append((rr,cc))
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr,nc=rr+dr,cc+dc
                    if 0<=nr<Hh and 0<=nc<Ww and not seen[nr][nc] and flipg[nr][nc]!=0:
                        seen[nr][nc]=True;stack.append((nr,nc))
            return comp
        for r in range(Hh):
            for c in range(Ww):
                if flipg[r][c]!=0 and not seen[r][c]:
                    out.append(flood(r,c))
        return out
    cs=get_comps(f)
    # find the line comp (widest, stays)
    line=max(cs,key=len)
    others=[c for c in cs if c is not line]
    others.sort(key=lambda c:max(r for r,_ in c))   # bottom asc
    res=[row[:] for row in f]; placed=set()
    for comp in others:
        best=None
        for d in range(Hh):
            if not any(r+d>=Hh or res[r+d][c] for r,c in comp) and True:
                # must not overlap line or placed comps... line handled by !=0 check below
                ok=all(res[r+d][c]==0 for r,c in comp)
                if ok: best=d; break
        d=best
        for r,c in comp:
            res[r+d][c]=f[r][c]
    # rebuild res properly with no-overlap constraint
    res=[row[:] for row in f]
    occ=[[False]*Ww for _ in range(Hh)]
    for comp in others:
        best=None
        for d in range(Hh):
            if all(res[r+d][c]==0 for r,c in comp):
                best=d; break
        for r,c in comp:
            res[r+d][c]=f[r][c]; occ[r+d][c]=True
    return [r[::-1] for r in res]

